mapper.update:
UPDATE portfolios
SET status = 'CLOSED',
    closed_at = #{closedAt},
    updated_at = #{closedAt}
WHERE portfolio_id = #{portfolioId}
  AND status = 'ACTIVE'

UPDATE portfolios
SET cash_balance = cash_balance - #{amount},
    updated_at = #{updatedAt}
WHERE portfolio_id = #{portfolioId}
  AND status = 'ACTIVE'
  AND cash_balance >= #{amount}

UPDATE portfolios
SET cash_balance = cash_balance + #{amount},
    updated_at = #{updatedAt}
WHERE portfolio_id = #{portfolioId}
  AND status = 'ACTIVE'
